package org.marketreview.nativeapp;
import org.json.*;
import java.util.*;
import java.util.regex.*;
import java.nio.*;
import java.nio.charset.*;
import java.security.*;
import java.time.*;
import java.util.function.BooleanSupplier;

/** Pure normalization. Source receipt time never substitutes for trading time. */
final class MarketOverviewModel {
 static final int MAX=8*1024*1024;
 static void need(boolean ok,String message){if(!ok)throw new IllegalArgumentException(message);}
 static void active(BooleanSupplier cancel){need(cancel==null||!cancel.getAsBoolean(),"已取消；未提交");}
 static String hash(byte[] bytes)throws Exception{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 static String decode(byte[] bytes,String charset)throws Exception{return Charset.forName(charset).newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();}
 static Object parse(byte[] bytes)throws Exception{need(bytes!=null&&bytes.length>0&&bytes.length<=MAX,"JSON须完整且不超过8MiB");JSONTokener t=new JSONTokener(decode(bytes,"UTF-8"));Object v=t.nextValue();need(t.nextClean()==0,"JSON尾部包含多余内容");return v;}
 static JSONObject emptyArchive()throws JSONException{return new JSONObject().put("schema","native-market-overview-archive/v1").put("revision",0).put("frames",new JSONArray());}
 static void validateSnapshot(JSONObject s)throws Exception{
  need("native-market-overview/v1".equals(s.optString("schema")),"不是市场全景观测格式");need(s.optString("id").matches("[a-f0-9]{64}"),"观测身份缺失");Instant.parse(s.getString("fetchedAt"));need("bounded-public-observations".equals(s.optString("scope"))&&s.has("unifiedSourceTime")&&s.isNull("unifiedSourceTime"),"观测时点或样本范围无效");JSONObject sections=s.getJSONObject("sections");need(sections.length()==4,"须明确四个分区");
  for(String key:new String[]{"indices","industry","concept","breadth"}){JSONObject r=sections.getJSONObject(key);need(r.opt("source") instanceof String&&r.opt("fetchedAt") instanceof String&&r.opt("sampleScope") instanceof String&&r.has("sourceTime")&&r.isNull("sourceTime"),"分区来源时点缺失");need(Arrays.asList("available","unavailable").contains(r.optString("availability")),"分区状态无效");if("available".equals(r.optString("availability"))){JSONObject data=r.getJSONObject("data");if(key.equals("industry")||key.equals("concept")){JSONArray rows=data.getJSONArray("rows");need(rows.length()<=100,"板块观测超过100条");Set<String> seen=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject b=rows.getJSONObject(i);String id=b.optString("code");need(key.equals(b.optString("kind"))&&id.matches("BK\\d{4}")&&!seen.contains(id),"板块身份或分类无效");seen.add(id);}}}}
  need(s.toString().getBytes(StandardCharsets.UTF_8).length<=2*1024*1024,"单个观测超过2MiB");
 }
 static void validateArchive(JSONObject a)throws Exception{need("native-market-overview-archive/v1".equals(a.optString("schema")),"不是市场全景档案");need(a.opt("revision") instanceof Number,"档案版本须为数字");double rev=a.optDouble("revision",-1);need(Double.isFinite(rev)&&rev>=0&&rev<=9007199254740991.0&&Math.floor(rev)==rev,"档案版本无效");JSONArray frames=a.getJSONArray("frames");need(frames.length()<=90,"档案超过90次观测");Set<String> ids=new HashSet<>();for(int i=0;i<frames.length();i++){JSONObject s=frames.getJSONObject(i);validateSnapshot(s);need(ids.add(s.getString("id")),"观测身份重复");}need(a.toString().getBytes(StandardCharsets.UTF_8).length<=MAX,"档案超过8MiB");}
 static JSONObject preview(byte[] bytes,JSONObject archive)throws Exception{validateArchive(archive);Object input=parse(bytes);need(input instanceof JSONObject,"导入须为JSON对象");JSONObject incoming=(JSONObject)input;JSONArray frames;if("native-market-overview/v1".equals(incoming.optString("schema"))){validateSnapshot(incoming);frames=new JSONArray().put(incoming);}else{validateArchive(incoming);frames=incoming.getJSONArray("frames");}JSONObject merged=new JSONObject(archive.toString());JSONArray rows=merged.getJSONArray("frames");Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++)ids.add(rows.getJSONObject(i).getString("id"));int added=0;for(int i=0;i<frames.length();i++){JSONObject s=frames.getJSONObject(i);if(!ids.add(s.getString("id")))continue;rows.put(new JSONObject(s.toString()).put("archiveProvenance","imported-unverified"));added++;}merged.put("revision",archive.getLong("revision")+1);validateArchive(merged);return new JSONObject().put("schema","native-market-overview-preview/v1").put("digest",hash(bytes)).put("expectedRevision",archive.getLong("revision")).put("added",added).put("merged",merged);}
 static JSONArray boardRows(JSONObject payload,String taxonomy)throws Exception{need(payload.optInt("rc",-1)==0,"板块源错误状态");JSONArray rows=payload.getJSONObject("data").getJSONArray("diff");need(rows.length()<=100,"公开板块响应超过请求边界");JSONArray out=new JSONArray();Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String id=r.optString("f12"),name=r.optString("f14");if(!id.matches("BK\\d{4}")||name.isEmpty()||!ids.add(id))continue;out.put(new JSONObject().put("code",id).put("name",name).put("kind",taxonomy).put("dailyChangePct",number(r.opt("f3"))).put("amount",number(r.opt("f6"))).put("mainNetInflow",number(r.opt("f62"))).put("leaderName",r.optString("f128")).put("sourceTime",JSONObject.NULL));}return out;}
 static JSONArray sampleRows(JSONArray rows)throws Exception{need(rows.length()<=300,"样本超过300条");JSONArray out=new JSONArray();Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String id=r.optString("symbol").toLowerCase(Locale.ROOT);Object c=number(r.opt("changepercent"));if(!id.matches("(sh|sz)\\d{6}")||c==JSONObject.NULL||!ids.add(id))continue;out.put(new JSONObject().put("fullId",id).put("name",r.opt("name")).put("changePct",c).put("price",number(r.opt("trade"))));}return out;}
 static final String[] IDS={"sh000001","sz399001","sz399006","sh000688","sh000300","sh000905","sh000852","sh000016"};
 static Object number(Object value){if(value==null||value==JSONObject.NULL||value instanceof Boolean)return JSONObject.NULL;try{String text=value.toString().trim();if(text.isEmpty())return JSONObject.NULL;double n=Double.parseDouble(text);return Double.isFinite(n)?n:JSONObject.NULL;}catch(Exception e){return JSONObject.NULL;}}
 static JSONObject indices(String raw,String fetchedAt)throws JSONException{
  Map<String,JSONObject> lookup=new HashMap<>();Matcher m=Pattern.compile("hq_str_s_((?:sh|sz)\\d{6})=\"([^\"]*)\"").matcher(raw);Set<String> allowed=new HashSet<>(Arrays.asList(IDS));
  while(m.find()){String id=m.group(1);String[] f=m.group(2).split(",",-1);if(!allowed.contains(id)||lookup.containsKey(id)||f.length<6)continue;Object price=number(f[1]),amount=number(f[5]);if(price==JSONObject.NULL||(double)price<=0)continue;lookup.put(id,new JSONObject().put("fullId",id).put("name",f[0]).put("price",price).put("changeAmount",number(f[2])).put("changePct",number(f[3])).put("volume",number(f[4])).put("amount",amount==JSONObject.NULL?amount:(double)amount*10000).put("publishedAt",JSONObject.NULL));}
  JSONArray rows=new JSONArray();for(String id:IDS)rows.put(lookup.containsKey(id)?lookup.get(id):new JSONObject().put("fullId",id).put("availability","unavailable").put("price",JSONObject.NULL).put("amount",JSONObject.NULL));Object sh=lookup.containsKey(IDS[0])?lookup.get(IDS[0]).get("amount"):JSONObject.NULL,sz=lookup.containsKey(IDS[1])?lookup.get(IDS[1]).get("amount"):JSONObject.NULL;
  return new JSONObject().put("schema","native-market-indices/v1").put("source","sina-public-index").put("fetchedAt",fetchedAt).put("publishedAt",JSONObject.NULL).put("indices",rows).put("receivedCount",lookup.size()).put("complete",lookup.size()==8).put("turnover",new JSONObject().put("shanghai",sh).put("shenzhen",sz).put("total",sh==JSONObject.NULL||sz==JSONObject.NULL?JSONObject.NULL:(double)sh+(double)sz));
 }
 static JSONObject breadth(JSONArray stocks,String sampleScope)throws JSONException{
  Set<String> seen=new HashSet<>();int n=0,up=0,down=0,strong=0,weak=0,sharp=0;double sum=0;
  for(int i=0;i<stocks.length();i++){JSONObject r=stocks.optJSONObject(i);if(r==null)continue;String id=r.optString("fullId");Object value=number(r.opt("changePct"));if(id.isEmpty()||seen.contains(id)||value==JSONObject.NULL)continue;seen.add(id);n++;double x=(double)value;sum+=x;if(x>0)up++;if(x<0)down++;if(x>=3)strong++;if(x<=-3)weak++;if(x<=-5)sharp++;}
  if(n==0)return new JSONObject().put("availability","unavailable").put("sampleScope",sampleScope).put("total",0).put("score",JSONObject.NULL);
  double b=100.0*up/n,avg=sum/n,score=b*.45+clamp(50+avg*9,0,100)*.30+clamp(50+220.0*(strong-weak)/n,0,100)*.25-clamp(140.0*sharp/n,0,25);
  return new JSONObject().put("availability","available").put("sampleScope",sampleScope).put("total",n).put("advancing",up).put("declining",down).put("flat",n-up-down).put("breadthPct",b).put("avgChangePct",avg).put("strongCount",strong).put("weakCount",weak).put("sharpDown",sharp).put("score",Math.floor(score+.5)).put("scoreProvenance","local-sentiment-formula-v1").put("wholeMarketClaim",false);
 }
 static double clamp(double x,double a,double z){return Math.max(a,Math.min(z,x));}
 static JSONArray rankBoards(JSONArray boards,String taxonomy,String metric,boolean descending,int limit)throws JSONException{
  if(!Arrays.asList("industry","concept").contains(taxonomy)||!Arrays.asList("dailyChangePct","amount","mainNetInflow","heatScore").contains(metric))return new JSONArray();
  List<JSONObject> rows=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<boards.length();i++){JSONObject r=boards.optJSONObject(i);if(r==null)continue;String code=r.optString("code");Object value=number(r.opt(metric));if(!taxonomy.equals(r.optString("kind"))||code.isEmpty()||seen.contains(code)||value==JSONObject.NULL)continue;JSONObject copy=new JSONObject(r.toString());copy.put(metric,value);rows.add(copy);seen.add(code);}
  rows.sort((a,b)->{double x=a.optDouble(metric),y=b.optDouble(metric);return x==y?a.optString("code").compareTo(b.optString("code")):Double.compare(descending?y:x,descending?x:y);});JSONArray out=new JSONArray();for(int i=0;i<Math.min(rows.size(),Math.max(1,Math.min(300,limit)));i++)out.put(rows.get(i));return out;
 }
 static JSONObject heatmap(JSONArray boards,String taxonomy,String mode)throws JSONException{JSONArray nodes=new JSONArray();int excluded=0;for(int i=0;i<boards.length();i++){JSONObject r=boards.optJSONObject(i);if(r==null||!taxonomy.equals(r.optString("kind")))continue;Object area=number(r.opt(mode.equals("flow")?"mainNetInflow":"amount")),color=number(r.opt(mode.equals("flow")?"mainNetInflow":"dailyChangePct"));if(area==JSONObject.NULL||color==JSONObject.NULL||Math.abs((double)area)<=0||!mode.equals("flow")&&(double)area<0){excluded++;continue;}nodes.put(new JSONObject().put("code",r.opt("code")).put("name",r.opt("name")).put("area",mode.equals("flow")?Math.abs((double)area):area).put("color",color));}return new JSONObject().put("nodes",nodes).put("excludedCount",excluded).put("taxonomy",taxonomy).put("mode",mode).put("availability",nodes.length()==0?"unavailable":"available").put("overlappingBoards",true).put("sumIsMarketTotal",false);}
}
